nxt[0]=1
prev=0
k=3
while True:
    end=prev
    for _ in range(k):
        end=nxt.get(end)
        if end is None:
            break
    if end is None:
        break
    after=nxt[end]
    cur=nxt[prev]
    old_first=cur
    back=after
    while cur!=after:
        forward=nxt[cur]
        nxt[cur]=back
        back,cur=cur,forward
    nxt[prev]=end
    prev=old_first
